async def act(page):
    # Wait for the page to load fully
    await page.wait_for_load_state('networkidle')

    # First, check for iframes that might contain the product edit form
    frames = page.frames
    product_frame = None
    for frame in frames:
        # Look for elements indicative of a product edit form in the frame
        price_in_frame = frame.get_by_role('textbox', name='Price', exact=True)
        if await price_in_frame.count() > 0:
            product_frame = frame
            break

    if product_frame:
        # Use the frame to interact with the price field
        price_field = product_frame.get_by_role('textbox', name='Price', exact=True)
    else:
        # No iframe found, search in the main page for the product edit section
        # Look for a form or region related to product editing
        product_section = page.get_by_role('form').filter(has=page.get_by_text('Product', exact=False))
        if await product_section.count() == 0:
            product_section = page.get_by_role('region').filter(has=page.get_by_text('Edit Product', exact=False))
        if await product_section.count() == 0:
            product_section = page.get_by_role('group').filter(has=page.get_by_text('Price', exact=False))

        if await product_section.count() == 0:
            # Fallback: search for any textbox with name 'Price' on the page
            price_field = page.get_by_role('textbox', name='Price', exact=True)
            if await price_field.count() == 0:
                raise Exception('Product edit section or price field not found.')
        else:
            # Search within the product section for the price field
            price_field = product_section.get_by_role('textbox', name='Price', exact=True)
            if await price_field.count() == 0:
                # Try case-insensitive or partial match
                price_field = product_section.get_by_role('textbox', name='price', exact=False)

    # Ensure price field is found
    if await price_field.count() == 0:
        raise Exception('Price field not found on the page.')

    # Get the current price value
    current_price_str = await price_field.input_value()
    try:
        current_price = float(current_price_str)
    except ValueError:
        raise Exception(f'Current price value "{current_price_str}" is not a valid number.')

    # Calculate new price: increase by 15%
    new_price = current_price * 1.15

    # Set the new price
    await price_field.fill(str(new_price))

    # Save the changes: look for a save button in the same context
    if product_frame:
        save_button = product_frame.get_by_role('button', name='Save', exact=True)
        if await save_button.count() == 0:
            save_button = product_frame.get_by_role('button', name='Save Product', exact=False)
    else:
        save_button = page.get_by_role('button', name='Save', exact=True)
        if await save_button.count() == 0:
            save_button = page.get_by_role('button', name='Save Product', exact=False)

    if await save_button.count() > 0:
        await save_button.click()
        # Wait for save to complete
        await page.wait_for_load_state('networkidle')
        print('Price updated and saved successfully.')
    else:
        print('Price updated, but save button not found. Changes may not be saved.')

    # Return the new price as the result
    return str(new_price)

